      "task.tip.session-id": "Laisse vide pour ouvrir une nouvelle session. Renseigné, l'IA travaille DANS cette session et garde tout son contexte. L'identifiant est celui affiché par « Reprendre au terminal » sur une session Mergerie existante — un UUID avec claude, un chemin de home avec copilot. Avec CLAUDE, attention : les sessions sont rangées par répertoire de projet, et Mergerie travaille dans son propre clone — un identifiant pris ailleurs n'y sera pas trouvé, le travail repartira d'une session neuve avec le contexte réinjecté, et la carte le signalera. Avec copilot, le home étant autonome, la reprise marche depuis n'importe où.",
